fn test_find_count_lists_only_total() {
    let dir = setup_workspace();

    write(dir.path().join("alpha.md"), "# Alpha\n\nContent.").unwrap();
    write(dir.path().join("beta.md"), "# Beta\n\nContent.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "2\n");
}

#[test]
fn test_find_count_with_refs_to_filter() {
    let dir = setup_workspace();

    write(
        dir.path().join("doc1.md"),
        indoc! {"
            # Doc One

            [target](target)
        "},
    )
    .unwrap();

    write(
        dir.path().join("doc2.md"),
        indoc! {"
            # Doc Two

            [target](target)
        "},
    )
    .unwrap();

    write(dir.path().join("doc3.md"), "# Doc Three\n\nNo refs.").unwrap();
    write(dir.path().join("target.md"), "# Target\n\nTarget content.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--refs-to", "target", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "2\n");
}

#[test]
fn test_find_count_with_metadata_filter() {
    let dir = setup_workspace();

    write(
        dir.path().join("ready.md"),
        indoc! {"
            ---
            status: ready
            ---

            # Ready
        "},
    )
    .unwrap();

    write(
        dir.path().join("done.md"),
        indoc! {"
            ---
            status: done
            ---

            # Done
        "},
    )
    .unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--meta", "status=ready", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "1\n");
}

#[test]
fn test_find_count_ignores_limit_and_format() {
    let dir = setup_workspace();

    for i in 1..=10 {
        write(
            dir.path().join(format!("doc{}.md", i)),
            format!("# Document {}\n\nContent.", i),
        )
        .unwrap();
    }

    let (stdout, stderr, success) = run_iwe(
        dir.path(),
        &["--limit", "3", "--format", "json", "--count"],
    );

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout, "10\n");
}
